class Solution {
public:
    vector<int> fallingSquares(vector<vector<int>>& positions) {
        vector<tuple<int, int, int>> intervals;
        vector<int> ans;
        int maxH = 0;

        for (auto& pos : positions) {
            int left = pos[0], size = pos[1];
            int right = left + size;
            int baseH = 0;
            for (auto& [prevL, prevR, prevH] : intervals) {
                if (left < prevR && right > prevL) {
                    baseH = max(baseH, prevH);
                }
            }
            int curH = baseH + size;
            intervals.push_back({left, right, curH});
            maxH = max(maxH, curH);
            ans.push_back(maxH);
        }
        return ans;
    }
};

class Solution {
    public List<Integer> fallingSquares(int[][] positions) {
        List<int[]> intervals = new ArrayList<>();
        List<Integer> ans = new ArrayList<>();
        int maxH = 0;

        for (int[] pos : positions) {
            int left = pos[0], size = pos[1];
            int right = left + size;
            int baseH = 0;
            for (int[] prev : intervals) {
                if (left < prev[1] && right > prev[0]) {
                    baseH = Math.max(baseH, prev[2]);
                }
            }
            int curH = baseH + size;
            intervals.add(new int[]{left, right, curH});
            maxH = Math.max(maxH, curH);
            ans.add(maxH);
        }
        return ans;
    }
}

